#include <bits/stdc++.h>
using namespace std;

using ll=long long;

const int N=10005, S=N-2, T=N-1;
const int M=2000010;
const int INF=2000000000;

int head[N], to[M], nxt[M], cap[M], cst[M], edgeIdx=1;

void add_edge(int u, int v, int capacity, int cost){
	to[++edgeIdx]=v; nxt[edgeIdx]=head[u]; head[u]=edgeIdx;
	cap[edgeIdx]=capacity; cst[edgeIdx]=cost;
	to[++edgeIdx]=u; nxt[edgeIdx]=head[v]; head[v]=edgeIdx;
	cap[edgeIdx]=0; cst[edgeIdx]=-cost;
}

queue<int> q;
long long dist[N];
bool inQ[N];

bool spfa(){
	memset(inQ, 0, sizeof(inQ));
	memset(dist, 0x3f, sizeof(dist));
	q.push(T); dist[T]=0; inQ[T]=true;
	while(!q.empty()){
		int x=q.front(); q.pop();
		inQ[x]=false;
		for(int i=head[x];i;i=nxt[i]){
			int y=to[i];
			if(cap[i^1] && dist[y]>dist[x]+cst[i^1]){
				dist[y]=dist[x]+cst[i^1];
				if(!inQ[y]){
					q.push(y);
					inQ[y]=true;
				}
			}
		}
	}
	return dist[S]<1e18;
}

int dfs(int x, int flowLimit, ll &totalCost){
	int flow=0; inQ[x]=true;
	if(x==T) return flowLimit;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(!cap[i] || inQ[y]) continue;
		if(dist[x]!=dist[y]+cst[i]) continue;
		int t=dfs(y, min(cap[i], flowLimit - flow), totalCost);
		cap[i]-=t; cap[i^1]+=t;
		flow+=t; totalCost+=t*cst[i];
		if(flow==flowLimit) break;
	}
	return flow;
}

long long min_cost_max_flow(){
	int totalFlow=0; ll totalCost=0;
	while(spfa()){
		memset(inQ, 0, sizeof(inQ));
		totalFlow+=dfs(S, 101, totalCost);
	}
	return totalCost;
}

int main(){
	int n,m,k,c,d,limit=101;
	cin>>n>>m>>k>>c>>d;
	for(int i=0;i<k;i++){
		int x; cin>>x; x--;
		add_edge(S,x,1,0);
	}
	for(int i=0;i<limit;i++)
		add_edge(i*n,T,k,c*i);
	for(int i=0;i<n;i++)
		for(int j=0;j<limit-1;j++)
			add_edge(i+j*n,i+(j+1)*n,k,0);
	while(m--){
		int x,y; cin>>x>>y; x--; y--;
		for(int i=0;i<limit-1;i++)
			for(int j=k-1;j>=0;j--){
				add_edge(x+i*n,y+(i+1)*n,1,d*(j*2+1));
				add_edge(y+i*n,x+(i+1)*n,1,d*(j*2+1));
			}
	}
	cout<<min_cost_max_flow();
	return 0;
}
